// Validate script metadata from Phase 2
const scriptData = $input.first().json;

if (!scriptData.script || typeof scriptData.script !== 'string') {
  throw new Error('Missing or invalid script field');
}

if (scriptData.script.length < 50) {
  throw new Error('Script too short (minimum 50 characters)');
}

if (scriptData.script.length > 50000) {
  throw new Error('Script too long (maximum 50,000 characters)');
}

return {
  json: {
    script: scriptData.script,
    title: scriptData.title || 'Untitled',
    script_id: scriptData.script_id || `script-${Date.now()}`,
    language: scriptData.language || 'en-US',
    duration_estimate: scriptData.duration_estimate || Math.ceil(scriptData.script.length / 150),
    script_length: scriptData.script.length,
    is_valid: true
  }
};

