// Split long scripts into chunks to avoid API limits
const script = items[0].json.script;
const MAX_CHUNK_SIZE = 5000;
const CHUNK_OVERLAP = 200;

const chunks = [];
let index = 0;

while (index < script.length) {
  let end = Math.min(index + MAX_CHUNK_SIZE, script.length);

  // Avoid splitting mid-sentence
  if (end < script.length) {
    const lastPeriod = script.lastIndexOf('.', end);
    if (lastPeriod > index + MAX_CHUNK_SIZE * 0.7) {
      end = lastPeriod + 1;
    }
  }

  chunks.push({
    text: script.substring(index, end),
    chunk_index: chunks.length,
    is_final: end === script.length
  });

  index = end - CHUNK_OVERLAP;
}

return chunks.map((chunk, i) => ({
  json: {
    ...items[0].json,
    chunk_text: chunk.text,
    chunk_index: chunk.chunk_index,
    total_chunks: chunks.length,
    is_final_chunk: chunk.is_final
  }
}));

