// Extract audio data from TTS response
// Supports both ElevenLabs (binary) and Google Cloud (base64) formats

const response = $input.first().json;

// Check if this is ElevenLabs response (binary audio)
if ($input.first().binary && $input.first().binary.data) {
  return {
    json: {
      audio_data: $input.first().binary.data,
      format: 'binary',
      provider: 'elevenlabs',
      chunk_index: $node['Split - Long Scripts'].json.chunk_index,
      audio_duration_estimate: Math.ceil($node['Split - Long Scripts'].json.chunk_text.length / 15) // ~15 chars per second
    }
  };
}

// Check if this is Google Cloud response (base64)
if (response.audioContent) {
  return {
    json: {
      audio_data: response.audioContent,
      format: 'base64',
      provider: 'google_cloud',
      chunk_index: $node['Split - Long Scripts'].json.chunk_index,
      audio_duration_estimate: Math.ceil($node['Split - Long Scripts'].json.chunk_text.length / 15)
    }
  };
}

throw new Error('No audio data in TTS response');

